// 45678901234567890123456789012345678901234567890123456789012345678901234567890

// Each child line fills the print width (80) exactly, then `{" "}` overflows it:
// the child stays on its line, the fill entry boundary does not count the pending space
<p>
  Run <span className="dynamic-info">{toolNameToolNameToolNameToolNameTo}</span>{" "}
  with args:{" "}
</p>;
<p>
  Abort {switchBlocked?.blockingOp === "merge" ? "MergeMergeMergeMe" : "Rebase"}{" "}
  &amp; Switch
</p>;
<p>
  <ValueText style={valueStyle}>{formatValue(num1)}</ValueText> {t("andandand")}{" "}
  <ValueText style={valueStyle}>{formatValue(num2)}</ValueText>
</p>;
